      "unit": "count",
      "source": "design"
    },
    "lobe_center_radius": {
      "value": 11.5,
      "unit": "mm",
      "source": "design"
    },
    "lobe_radius": {
      "value": 3.4,
      "unit": "mm",
      "source": "design"
    },
    "nut_af": {
      "value": 8.0,
      "unit": "mm",
      "source": "catalog",
      "ref": "ISO 4032 M5"
    },
    "nut_height": {
      "value": 4.7,
      "unit": "mm",
      "source": "catalog",
      "ref": "ISO 4032 M5"
    },
    "nut_pocket_af": {
      "value": 7.9,
      "unit": "mm",
      "source": "guessed"
    },
    "nut_pocket_depth": {
      "value": 5.2,
      "unit": "mm",
      "source": "design"
    },
    "bolt_clearance_d": {
      "value": 5.5,
      "unit": "mm",
      "source": "design"
    },
    "bolt_nominal_d": {
      "value": 5.0,
      "unit": "mm",
      "source": "catalog",
      "ref": "M5 thread"
    }
  },
  "parts": [
    {
      "id": "hand_knob",
      "role": "final",
      "material": "PLA",
      "code": "import math\n\ndef build(p):\n    # A round centre with eight overlapping grip lobes. The XY face at z=0\n    # is the bed face and also the nut-insertion face.\n    body = cq.Workplane(\"XY\").circle(p.core_radius).extrude(p.knob_thickness)\n    for i in range(p.lobe_count):\n        a = 2.0 * math.pi * i / p.lobe_count\n        x = p.lobe_center_radius * math.cos(a)\n        y = p.lobe_center_radius * math.sin(a)\n        lobe = cq.Workplane(\"XY\").center(x, y).circle(p.lobe_radius).extrude(p.knob_thickness)\n        body = body.union(lobe)\n\n    # Hex pocket is open on the bed face. Across-flats is the specified fit\n    # dimension; the far roof remains intact around the M5 clearance bore.\n    circumradius = p.nut_pocket_af / math.sqrt(3.0)\n    pts = [(circumradius * math.cos(math.radians(60 * i)),\n            circumradius * math.sin(math.radians(60 * i))) for i in range(6)]\n    pocket = cq.Workplane(\"XY\").polyline(pts).close().extrude(p.nut_pocket_depth)\n    body = body.cut(pocket)\n\n    bore = cq.Workplane(\"XY\").circle(p.bolt_clearance_d / 2.0).extrude(p.knob_thickness)\n    body = body.cut(bore)\n    return body",
      "print_orientation": "Lay the broad circular face with the hex nut pocket on the build plate (z=0); print the knob upright, with the opposite face at the top. No supports are needed.",
      "use_orientation": "The pocket-opening face is the nut insertion side. The opposite face is the bolt-entry/exit face."
    }
  ],
  "hardware": [
    {
      "id": "m5_nut",
      "ref": "ISO 4032 M5",
      "qty": 1
    }
  ],
  "criteria": [
    {
      "id": "nut_press_fit",
