      "relation": "engages",
      "hardware": "m5_nut",
      "check": {
        "method": "measure",
        "description": "Press the nut into the pocket by hand. It should be snug enough to remain seated when the knob is turned upside down; tune nut_pocket_af in 0.05 mm steps if needed."
      }
    },
    {
      "id": "nut_axial_stop",
      "part": "hand_knob",
      "feature": "solid roof surrounding the 5.5 mm through-bore",
      "relation": "supports",
      "hardware": "m5_nut",
      "check": {
        "method": "none",
        "description": "The nut pocket ends inside the knob, while the smaller through-bore leaves a retaining shoulder at the far side."
      }
    },
    {
      "id": "m5_bolt_clearance",
      "part": "hand_knob",
      "feature": "5.5 mm axial through-bore",
      "relation": "clears",
      "clearance_mm": 0.5,
      "params": [
        "bolt_clearance_d",
        "bolt_nominal_d"
      ],
      "check": {
        "method": "measure",
        "description": "Confirm the user's M5 bolt passes through the bore and threads into the captive nut."
      }
    }
  ],
  "manual": [
    {
      "n": "1",
      "text": "Print hand_knob flat with the hex pocket facing the build plate. Remove any first-layer elephant-foot material from the pocket entrance if present.",
      "parts": [
        "hand_knob"
      ]
    },
    {
      "n": "2",
      "text": "Place m5_nut squarely at the pocket opening and press it in by hand until it seats against the internal roof. Do not force it with a tool; if it is excessively tight, increase nut_pocket_af slightly and reprint.",
      "parts": [
        "hand_knob"
      ],
      "hardware": [
        "m5_nut"
      ]
    },
    {
      "n": "3",
      "text": "Turn the knob upside down to check that the nut stays captured. Pass an M5 bolt through the opposite face and thread it into the nut.",
      "parts": [
        "hand_knob"
      ],
      "hardware": [
        "m5_nut"
      ]
    }
  ]
}
